#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=11

# Everything runs from the repository root: the image is built from the Dockerfile here, and
# the captured values are written beside it.
cd "$(git rev-parse --show-toplevel)"

# Not `.env`: that file is the self-hoster's docker compose config. `.env.*` is gitignored
# already, so the Neon URL and the auth secret stay out of git.
ENV_FILE=".env.hosted-deploy"

REGION="asia-southeast1"
SERVICE="job-tracker"
AR_REPO="job-tracker"
NEON_REGION="aws-ap-southeast-1"
REPO_SLUG="yapjunyu/job-tracker"
POOL="github"
PROVIDER="job-tracker"

banner "The hosted copy on Cloud Run (issue #5)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Prerequisites"
say "Checking the tools this wizard drives."
for tool in gcloud gh docker openssl curl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing. Install it, then re-run."; exit 1; }
  note "found $tool"
done
gcloud auth list --filter=status:ACTIVE --format="value(account)" 2>/dev/null | grep -q . \
  || { warn "No active Google Cloud account. Run: gcloud auth login"; exit 1; }
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in. Run: gh auth login"; exit 1; }
docker info >/dev/null 2>&1 \
  || { warn "Docker isn't running. Start Docker Desktop, then re-run."; exit 1; }
say ""
say "Cloud Run needs a billing account even to stay inside the free tier."
if ! gcloud billing accounts list --format="value(name)" 2>/dev/null | grep -q .; then
  warn "This account can see no billing account."
  step "On the page opening now, create one or accept the credits you were granted."
  open_url "https://console.cloud.google.com/billing"
  pause "Press Enter once a billing account is listed there."
fi
gcloud billing accounts list --format="table(name,displayName,open)" || true
ask GCP_BILLING_ACCOUNT "Billing account id (the 0X0X0X-0X0X0X-0X0X0X part):"
write_env GCP_BILLING_ACCOUNT "$GCP_BILLING_ACCOUNT"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The Google Cloud project"
say "A project of its own keeps the spend cap and the clean-up policy off your other work."
SUGGESTED="job-tracker-$(openssl rand -hex 3)"
note "Project ids are globally unique, so here is one with a suffix: $SUGGESTED"
ask GCP_PROJECT_ID "Project id [$SUGGESTED]:"
[[ -n "$GCP_PROJECT_ID" ]] || GCP_PROJECT_ID="$SUGGESTED"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
if gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  note "$GCP_PROJECT_ID already exists, so it is reused"
else
  say "Creating $GCP_PROJECT_ID ..."
  gcloud projects create "$GCP_PROJECT_ID" --name="job-tracker"
fi
say "Linking billing ..."
gcloud billing projects link "$GCP_PROJECT_ID" --billing-account="$GCP_BILLING_ACCOUNT"
say "Enabling the APIs (a minute or so) ..."
gcloud services enable \
  run.googleapis.com artifactregistry.googleapis.com secretmanager.googleapis.com \
  iamcredentials.googleapis.com sts.googleapis.com \
  --project="$GCP_PROJECT_ID"
GCP_PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format="value(projectNumber)")
write_env GCP_PROJECT_NUMBER "$GCP_PROJECT_NUMBER"
RUNTIME_SA="${GCP_PROJECT_NUMBER}-compute@developer.gserviceaccount.com"
note "Your gcloud default project is untouched: every command here passes --project."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: the database"
say "Free Neon in Singapore, beside Cloud Run, so a query costs no round trip (ADR-0001)."
open_url "https://console.neon.tech/app/projects/new"
step "Name the project job-tracker."
step "Set the region to AWS Asia Pacific 1 / Singapore ($NEON_REGION)."
step "Keep the Free plan, then create the project."
step "In the Connect panel, copy the pooled connection string: its host contains -pooler."
note "Pooled, because a cold Cloud Run instance opens its own connections on every wake."
ask_secret NEON_DATABASE_URL "Paste the connection string:"
case "$NEON_DATABASE_URL" in
  postgres://*|postgresql://*) : ;;
  *) warn "That isn't a postgres:// connection string. Re-run when you have it."; exit 1 ;;
esac
write_env NEON_DATABASE_URL "$NEON_DATABASE_URL"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Secret Manager: the database URL and the auth secret"
say "Cloud Run reads both at start-up. Neither is ever stored in GitHub."
upsert_secret() {
  if gcloud secrets describe "$1" --project="$GCP_PROJECT_ID" >/dev/null 2>&1; then
    printf '%s' "$2" | gcloud secrets versions add "$1" --data-file=- \
      --project="$GCP_PROJECT_ID" >/dev/null
    note "added a new version of $1"
  else
    printf '%s' "$2" | gcloud secrets create "$1" --data-file=- \
      --replication-policy=automatic --project="$GCP_PROJECT_ID" >/dev/null
    note "created $1"
  fi
}
AUTH_SECRET=$(_existing AUTH_SECRET || true)
if [[ -z "$AUTH_SECRET" ]]; then
  AUTH_SECRET=$(openssl rand -base64 32)
  note "generated a fresh AUTH_SECRET; changing it later signs every device out"
fi
write_env AUTH_SECRET "$AUTH_SECRET"
upsert_secret database-url "$NEON_DATABASE_URL"
upsert_secret auth-secret "$AUTH_SECRET"
for secret in database-url auth-secret; do
  gcloud secrets add-iam-policy-binding "$secret" \
    --member="serviceAccount:${RUNTIME_SA}" \
    --role="roles/secretmanager.secretAccessor" \
    --project="$GCP_PROJECT_ID" >/dev/null
done
note "the Cloud Run runtime account may read both"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Artifact Registry: the image repository"
gcloud artifacts repositories describe "$AR_REPO" --location="$REGION" \
  --project="$GCP_PROJECT_ID" >/dev/null 2>&1 \
  || gcloud artifacts repositories create "$AR_REPO" --repository-format=docker \
       --location="$REGION" --description="job-tracker images" --project="$GCP_PROJECT_ID"
say "Clean-up policy: keep the last 3 images, drop anything older than a week."
note "Artifact Registry can't be spend-capped, so it has to stay inside the free allowance."
POLICY_FILE=$(mktemp)
cat > "$POLICY_FILE" <<'JSON'
[
  {
    "name": "keep-last-3",
    "action": { "type": "Keep" },
    "mostRecentVersions": { "keepCount": 3 }
  },
  {
    "name": "delete-older-than-a-week",
    "action": { "type": "Delete" },
    "condition": { "tagState": "any", "olderThan": "7d" }
  }
]
JSON
gcloud artifacts repositories set-cleanup-policies "$AR_REPO" --location="$REGION" \
  --project="$GCP_PROJECT_ID" --policy="$POLICY_FILE"
rm -f "$POLICY_FILE"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "The first image"
say "The service can't be created without an image, so this one is built here."
say "Every later image is built by GitHub Actions on merge to main."
IMAGE="${REGION}-docker.pkg.dev/${GCP_PROJECT_ID}/${AR_REPO}/app"
write_env IMAGE "$IMAGE"
gcloud auth configure-docker "${REGION}-docker.pkg.dev" --quiet
say "Building for linux/amd64, which is what Cloud Run runs (a few minutes) ..."
docker build --platform linux/amd64 --tag "${IMAGE}:setup" .
docker push "${IMAGE}:setup"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The Cloud Run service"
DEFAULT_EMAIL=$(gh api user --jq '.email // empty' 2>/dev/null || true)
[[ -n "$DEFAULT_EMAIL" ]] || DEFAULT_EMAIL=$(git config user.email 2>/dev/null || true)
say "The hosted copy is invite-only, so strangers can't use up the free quotas."
ask INVITE_LIST "Addresses allowed to sign up, comma separated [$DEFAULT_EMAIL]:"
[[ -n "$INVITE_LIST" ]] || INVITE_LIST="$DEFAULT_EMAIL"
write_env INVITE_LIST "$INVITE_LIST"
say "Creating the service: scale to zero, at most 2 instances, CPU only during a request."
# `^|^` tells gcloud to split on | instead of a comma, so an invite list of several addresses
# survives. Migrations run at start-up, so the startup probe is given room to wait for them.
gcloud run deploy "$SERVICE" \
  --project="$GCP_PROJECT_ID" --region="$REGION" --image="${IMAGE}:setup" \
  --allow-unauthenticated --port=3000 --min-instances=0 --max-instances=2 --cpu-throttling \
  --startup-probe="httpGet.path=/api/health,httpGet.port=3000,timeoutSeconds=5,periodSeconds=5,failureThreshold=10" \
  --set-secrets="DATABASE_URL=database-url:latest,AUTH_SECRET=auth-secret:latest" \
  --set-env-vars="^|^INVITE_LIST=${INVITE_LIST}"
SERVICE_URL=$(gcloud run services describe "$SERVICE" --region="$REGION" \
  --project="$GCP_PROJECT_ID" --format="value(status.url)")
write_env SERVICE_URL "$SERVICE_URL"
# APP_URL can only be set now: it is the URL the service was just given, and session cookies
# need it to be the real HTTPS origin.
gcloud run services update "$SERVICE" --project="$GCP_PROJECT_ID" --region="$REGION" \
  --update-env-vars="APP_URL=${SERVICE_URL}" >/dev/null
note "the app is live at $SERVICE_URL"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Workload Identity Federation"
say "GitHub Actions presents a short-lived token and swaps it for Google credentials."
say "No service-account key is created, so there is none to leak."
DEPLOYER="github-deployer@${GCP_PROJECT_ID}.iam.gserviceaccount.com"
gcloud iam workload-identity-pools describe "$POOL" --location=global \
  --project="$GCP_PROJECT_ID" >/dev/null 2>&1 \
  || gcloud iam workload-identity-pools create "$POOL" --location=global \
       --display-name="GitHub Actions" --project="$GCP_PROJECT_ID"
gcloud iam workload-identity-pools providers describe "$PROVIDER" \
  --workload-identity-pool="$POOL" --location=global \
  --project="$GCP_PROJECT_ID" >/dev/null 2>&1 \
  || gcloud iam workload-identity-pools providers create-oidc "$PROVIDER" \
       --workload-identity-pool="$POOL" --location=global \
       --issuer-uri="https://token.actions.githubusercontent.com" \
       --attribute-mapping="google.subject=assertion.sub,attribute.repository=assertion.repository" \
       --attribute-condition="assertion.repository == '${REPO_SLUG}'" \
       --project="$GCP_PROJECT_ID"
gcloud iam service-accounts describe "$DEPLOYER" --project="$GCP_PROJECT_ID" >/dev/null 2>&1 \
  || gcloud iam service-accounts create github-deployer \
       --display-name="GitHub Actions deployer" --project="$GCP_PROJECT_ID"
for role in roles/run.admin roles/artifactregistry.writer; do
  gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
    --member="serviceAccount:${DEPLOYER}" --role="$role" >/dev/null
done
# A deploy starts the container as the runtime account, so the deployer must act as it.
gcloud iam service-accounts add-iam-policy-binding "$RUNTIME_SA" \
  --member="serviceAccount:${DEPLOYER}" --role="roles/iam.serviceAccountUser" \
  --project="$GCP_PROJECT_ID" >/dev/null
# Only workflows in this repository may become the deployer.
gcloud iam service-accounts add-iam-policy-binding "$DEPLOYER" \
  --member="principalSet://iam.googleapis.com/projects/${GCP_PROJECT_NUMBER}/locations/global/workloadIdentityPools/${POOL}/attribute.repository/${REPO_SLUG}" \
  --role="roles/iam.workloadIdentityUser" --project="$GCP_PROJECT_ID" >/dev/null
GCP_WIF_PROVIDER="projects/${GCP_PROJECT_NUMBER}/locations/global/workloadIdentityPools/${POOL}/providers/${PROVIDER}"
write_env GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
write_env GCP_DEPLOY_SERVICE_ACCOUNT "$DEPLOYER"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "The GitHub repository variables"
say "These three are all deploy.yml needs. There are no GitHub secrets to set."
set_var GCP_PROJECT_ID "$GCP_PROJECT_ID"
set_var GCP_WIF_PROVIDER "$GCP_WIF_PROVIDER"
set_var GCP_DEPLOY_SERVICE_ACCOUNT "$GCP_DEPLOY_SERVICE_ACCOUNT"
note "From here, a merge to main runs the checks, builds the image and deploys it."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "The spend cap"
say "gcloud has no spend-cap command, so this one stage is in the console."
open_url "https://console.cloud.google.com/billing/${GCP_BILLING_ACCOUNT}/budgets"
step "Create new budget, then pick Spend cap enforcement, not Alerts only."
step "Name it job-tracker cap, then Next."
step "Scope: project ${GCP_PROJECT_ID}, service Cloud Run. Then Next."
step "Amount: 10 USD, then Finish. Alerts at 50%, 80% and 100% come with it."
warn "A spend cap is not a hard stop: usage reporting lags, so a small overspend is possible."
note "Cloud Run is paused for the rest of the month once the cap is hit, until you lift it."
pause "Press Enter once the budget exists."

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Sign in, then measure the cold start"
open_url "$SERVICE_URL"
step "Sign up with one of the invited addresses. Any other address must be refused."
pause "Press Enter once you are signed in."
say ""
say "ADR-0001 keeps the frontend on Cloud Run only while a cold start stays under ~1.5 s,"
say "so issue #5 asks for the first load on a cold instance to be recorded."
note "Cloud Run idles the instance down after roughly 15 minutes without a request."
if confirm "Has it been idle 15+ minutes, so this would really be a cold start?"; then
  COLD=$(curl -s -o /dev/null -w "%{time_total}" "${SERVICE_URL}/") || COLD="(curl failed)"
  say "First load: ${COLD}s"
  if confirm "Record that as a comment on issue #5?"; then
    gh issue comment 5 --body "Cold start, first page load after idle: ${COLD}s (measured with curl against ${SERVICE_URL}/ in ${REGION}). ADR-0001 defers the Cloudflare Pages move while this stays under about 1.5 s."
    note "commented on issue #5"
  fi
else
  SKIPPED+=("measure the cold start once idle 15+ min: curl -s -o /dev/null -w '%{time_total}' ${SERVICE_URL}/ , then gh issue comment 5")
fi

finish
}

run_wizard "$@"; exit
